#!/bin/zsh
set -euo pipefail
cd "$(dirname "$0")/../.."
source scripts/lib/test-env.sh
missioncontrol_test_init mcp-bridge
xcrun swiftc -module-cache-path "$MISSIONCONTROL_TEST_MODULE_CACHE" MissionControl/Infrastructure/Models/Models.swift MissionControl/Infrastructure/Actions/ActionModels.swift MissionControl/Infrastructure/Usage/AIUsage.swift MissionControl/Assistant/Provider/ChatGPTStream.swift MissionControl/Assistant/Tools/PAToolProtocol.swift MissionControl/Projects/LifeWorkspace.swift MissionControl/Projects/LifeProjectPlacement.swift MissionControl/Projects/LifeWorkspaceQuery.swift MissionControl/Projects/LifeWorkspaceToolSchema.swift MissionControl/Memory/Records/PAMemory.swift MissionControl/Memory/Notebook/LifeNotebook.swift MissionControl/Memory/Notebook/LifeOrganisation.swift MissionControl/Assistant/MCP/MCPBridgeContract.swift MissionControl/Assistant/MCP/MCPBridgeHTTP.swift Tests/Assistant/MCPBridgeChecks.swift -o "$MISSIONCONTROL_TEST_BIN"
"$MISSIONCONTROL_TEST_BIN"
xcrun swiftc -module-cache-path "$MISSIONCONTROL_TEST_MODULE_CACHE" MissionControl/Infrastructure/Models/Models.swift MissionControl/Infrastructure/Storage/Cache.swift MissionControl/Infrastructure/Storage/LocalRecordRepository.swift MissionControl/Infrastructure/Actions/ActionModels.swift MissionControl/Infrastructure/Actions/ActionReceiptStore.swift MissionControl/Infrastructure/Actions/NativeCreation.swift MissionControl/Infrastructure/Actions/NativeEditing.swift MissionControl/Infrastructure/Usage/AIUsage.swift MissionControl/Assistant/Provider/ChatGPTStream.swift MissionControl/Assistant/Tools/PAToolProtocol.swift MissionControl/Projects/LifeWorkspace.swift MissionControl/Projects/LifeProjectPlacement.swift MissionControl/Projects/LifeWorkspaceQuery.swift MissionControl/Projects/LifeWorkspaceToolSchema.swift MissionControl/Memory/Records/PAMemory.swift MissionControl/Memory/Notebook/LifeNotebook.swift MissionControl/Memory/Notebook/LifeOrganisation.swift MissionControl/Assistant/MCP/MCPBridgeContract.swift MissionControl/Assistant/MCP/MCPBridgeHTTP.swift MissionControl/Assistant/MCP/MCPBridgeListener.swift MissionControl/Assistant/MCP/MCPBridgeService.swift Tests/Assistant/MCPBridgeServiceChecks.swift -o "$MISSIONCONTROL_TEST_WORK_DIR/service-checks"
"$MISSIONCONTROL_TEST_WORK_DIR/service-checks"
# Already installed dependencies only; this check never downloads or starts 3PO.
node --test MCPBridge/tests/server.test.mjs
